/**
 * InstaPay QR codes printed on the statement of account, so a customer can
 * settle from their phone without asking which bank to use.
 *
 * Each is the QR square cropped out of the bank's own share sheet. Every one
 * was re-decoded after cropping and again at the size it prints (44mm), and
 * the payload checked byte-for-byte against the original — a QR that does not
 * scan is worse than no QR at all. The clean sources are thresholded to pure
 * black and white, which is both crisper and far smaller; BDO's source is a
 * lossy JPEG whose noise survives thresholding, so it keeps its grey detail.
 *
 * Inlined as data URLs because the PDF needs bytes, not a URL. This module is
 * only pulled in when a statement is generated, so it costs nothing otherwise.
 *
 * To change these: export fresh QRs from each bank app and re-run the
 * extraction, checking each still decodes to the same payload.
 */
export interface PaymentQr {
  bank: string
  /** Masked account, as the bank app shows it. */
  account: string
  accountName: string
  /** PNG data URL of the QR square. */
  image: string
}

